insert into ideas (id, topic_id, source_id, title, body) values
  ('the-lean-startup-1', 'business', 'the-lean-startup', 'Build, measure, learn', 'Treat every product idea as an experiment. Build the smallest thing that tests it, measure how people actually respond, and learn whether to keep going or change course.'),
  ('the-lean-startup-2', 'business', 'the-lean-startup', 'The minimum viable product', 'An MVP isn''t a cheap version of the final product; it''s the quickest way to start learning. Sometimes it''s just a landing page or a manual service behind the scenes.'),
  ('the-lean-startup-3', 'business', 'the-lean-startup', 'Pivot or persevere', 'At regular points, look at the evidence and decide honestly: is this working, or should we change a fundamental part of the strategy?'),
  ('the-lean-startup-4', 'business', 'the-lean-startup', 'Vanity metrics', 'Total sign-ups and page views can rise while the business fails. Track numbers that show real behaviour, like how many users come back.'),
  ('the-lean-startup-5', 'business', 'the-lean-startup', 'Validated learning', 'Progress in a startup isn''t lines of code or features shipped. It''s evidence about what customers truly want.'),
  ('zero-to-one-1', 'business', 'zero-to-one', 'Zero to one versus one to n', 'Copying what works takes the world from one to n. Creating something new takes it from zero to one. The biggest value comes from the latter.'),
  ('zero-to-one-2', 'business', 'zero-to-one', 'The contrarian question', 'Ask: what important truth do very few people agree with you on? Good businesses are often built on a secret others have missed.'),
  ('zero-to-one-3', 'business', 'zero-to-one', 'Start small and monopolize', 'Dominate a small, specific market first, then expand. Competing in a huge crowded market from day one is a fast way to make no profit.'),
  ('zero-to-one-4', 'business', 'zero-to-one', 'Competition erodes profit', 'In perfect competition, profits get competed away. Lasting businesses have something unique, like proprietary technology or network effects.'),
  ('good-to-great-1', 'business', 'good-to-great', 'First who, then what', 'Great companies first got the right people on the bus and the wrong people off, and only then figured out where to drive it.'),
  ('good-to-great-2', 'business', 'good-to-great', 'Level 5 leadership', 'The leaders behind great companies combined deep personal humility with fierce determination. They gave credit away and took blame themselves.'),
  ('good-to-great-3', 'business', 'good-to-great', 'The hedgehog concept', 'Find the intersection of three circles: what you can be the best in the world at, what drives your economic engine, and what you''re deeply passionate about.'),
  ('good-to-great-4', 'business', 'good-to-great', 'The flywheel', 'Greatness rarely arrives in one dramatic moment. It''s built by consistent pushes on a heavy wheel until momentum carries it.'),
  ('good-to-great-5', 'business', 'good-to-great', 'Confront the brutal facts', 'Keep unwavering faith that you''ll succeed, while honestly facing the harsh reality of your current situation.'),
  ('the-innovators-dilemma-1', 'business', 'the-innovators-dilemma', 'Disruptive innovation', 'Disruptors often start with a simpler, cheaper product that seems worse to existing customers. They win overlooked buyers first, then improve until they take the main market.'),
  ('the-innovators-dilemma-2', 'business', 'the-innovators-dilemma', 'Listening to customers can mislead', 'Big companies focus on their best customers'' requests, which pushes them upmarket and leaves the low end open to newcomers.'),
  ('the-innovators-dilemma-3', 'business', 'the-innovators-dilemma', 'Small markets don''t excite big companies', 'A new market worth a few million can''t move the needle for a giant, so it gets ignored until it''s too late.'),
  ('the-innovators-dilemma-4', 'business', 'the-innovators-dilemma', 'Create a separate unit', 'Successful incumbents often handle disruption by setting up an independent team with its own goals and cost structure.'),
  ('the-hard-thing-1', 'business', 'the-hard-thing', 'There''s no recipe', 'Management books describe how to avoid problems. Hard things are the situations with no clean answer, where you have to choose the least bad option.'),
  ('the-hard-thing-2', 'business', 'the-hard-thing', 'The struggle', 'Every founder goes through periods when nothing works and quitting looks sensible. Getting through them is part of the job, not a sign you''ve failed.'),
  ('the-hard-thing-3', 'business', 'the-hard-thing', 'Take care of people, products and profits, in that order', 'Without good people, you won''t build good products, and without good products the profits won''t come.'),
  ('the-hard-thing-4', 'business', 'the-hard-thing', 'Tell it like it is', 'When things go badly, being open with your team builds trust. Hiding bad news makes the hard thing harder.'),
  ('rework-1', 'business', 'rework', 'Planning is guessing', 'Long-term business plans pretend you can predict the future. Decide what you''ll do this week instead, and adjust as you learn.'),
  ('rework-2', 'business', 'rework', 'Small is fine', 'Not every company needs to grow huge. Staying small and profitable can mean more freedom and less stress.'),
  ('rework-3', 'business', 'rework', 'Build half a product, not a half-assed product', 'Cut features ruthlessly and do what''s left really well.'),
  ('rework-4', 'business', 'rework', 'Meetings are toxic', 'A one-hour meeting with ten people costs ten hours of work. Hold fewer, shorter ones, with a clear agenda.'),
  ('rework-5', 'business', 'rework', 'Say no by default', 'Each yes adds complexity. Saying no to most feature requests keeps a product focused.'),
  ('so-good-they-cant-ignore-you-1', 'career', 'so-good-they-cant-ignore-you', 'Passion follows mastery', 'Most people don''t discover a pre-existing passion. They become passionate about work they''ve become very good at.'),
  ('so-good-they-cant-ignore-you-2', 'career', 'so-good-they-cant-ignore-you', 'Career capital', 'Rare and valuable skills are the currency you trade for great jobs: autonomy, creativity and impact.'),
  ('so-good-they-cant-ignore-you-3', 'career', 'so-good-they-cant-ignore-you', 'The craftsman mindset', 'Focus on what value you can offer, not on what the job offers you. Getting better is the path to loving your work.'),
  ('so-good-they-cant-ignore-you-4', 'career', 'so-good-they-cant-ignore-you', 'Deliberate practice', 'Getting better requires stretching beyond comfort, with feedback. Coasting at what you already know builds no capital.'),
  ('range-1', 'career', 'range', 'Kind and wicked learning environments', 'Chess and golf have clear rules and fast feedback, so early specialization works. Most of life is messier, and broad experience helps more.'),
  ('range-2', 'career', 'range', 'The sampling period', 'Many top performers tried several activities before settling. Exploring helps you find a good match, which matters more than an early start.'),
  ('range-3', 'career', 'range', 'Analogical thinking', 'People with broad experience can borrow solutions from unrelated fields. Outsiders often solve problems that insiders are stuck on.'),
  ('range-4', 'career', 'range', 'Late starters aren''t behind', 'Switching paths isn''t wasted time. What you learned elsewhere often becomes an unusual advantage.'),
  ('designing-your-life-1', 'career', 'designing-your-life', 'Prototype your career', 'Before making a big change, test it in small ways: talk to people in the field, shadow someone, take a short project.'),
  ('designing-your-life-2', 'career', 'designing-your-life', 'Odyssey plans', 'Sketch three different five-year lives: your current path, what you''d do if that disappeared, and what you''d do if money and judgment didn''t matter.'),
  ('designing-your-life-3', 'career', 'designing-your-life', 'Gravity problems', 'Some problems can''t be solved, like gravity. Accept them and design around them instead of wasting energy fighting.'),
  ('designing-your-life-4', 'career', 'designing-your-life', 'Track your energy', 'For a few weeks, note which activities energize or drain you. The patterns reveal what work fits you.'),
  ('the-7-habits-1', 'career', 'the-7-habits', 'Be proactive', 'Between what happens and how you respond, there''s a space. Focus on what you can influence rather than what you can''t.'),
  ('the-7-habits-2', 'career', 'the-7-habits', 'Begin with the end in mind', 'Picture what you want people to say about you at the end of your life. Let that vision guide your daily choices.'),
  ('the-7-habits-3', 'career', 'the-7-habits', 'Put first things first', 'Important but not urgent activities, like planning, relationships and health, are where real effectiveness lies. Schedule them before urgent trivia.'),
  ('the-7-habits-4', 'career', 'the-7-habits', 'Seek first to understand', 'Most people listen with the intent to reply. Listen to understand first, and you''ll be understood more easily.'),
  ('the-7-habits-5', 'career', 'the-7-habits', 'Sharpen the saw', 'Regularly renew your body, mind, relationships and spirit. Without maintenance, effectiveness wears down.'),
  ('grit-1', 'career', 'grit', 'Effort counts twice', 'Talent times effort equals skill; skill times effort equals achievement. Effort shows up in both steps.'),
  ('grit-2', 'career', 'grit', 'Grit is passion plus perseverance', 'Gritty people stick with long-term goals for years, through setbacks and boredom.'),
  ('grit-3', 'career', 'grit', 'Interest comes first', 'Passion usually starts with a spark of interest, then grows through practice and finding purpose.'),
  ('grit-4', 'career', 'grit', 'Hope as a habit', 'Gritty people expect their efforts to improve their future. That optimism keeps them trying after failures.'),
  ('how-to-win-friends-1', 'communication', 'how-to-win-friends', 'Don''t criticize, condemn or complain', 'Criticism makes people defensive and rarely changes behaviour. Try to understand why people do what they do instead.'),
  ('how-to-win-friends-2', 'communication', 'how-to-win-friends', 'Become genuinely interested in others', 'You''ll make more friends in two months by being interested in other people than in two years trying to get them interested in you.'),
  ('how-to-win-friends-3', 'communication', 'how-to-win-friends', 'Remember names', 'A person''s name is, to them, one of the sweetest sounds. Using it shows you see them as an individual.'),
  ('how-to-win-friends-4', 'communication', 'how-to-win-friends', 'Talk in terms of their interests', 'To persuade someone, start from what they care about, not what you want.'),
  ('how-to-win-friends-5', 'communication', 'how-to-win-friends', 'Let the other person save face', 'Even when you''re right, a little kindness that lets someone keep their dignity goes a long way.'),
  ('crucial-conversations-1', 'communication', 'crucial-conversations', 'Start with heart', 'Before a difficult talk, ask: what do I really want for myself, for them and for the relationship? It keeps you from trying to just win.'),
  ('crucial-conversations-2', 'communication', 'crucial-conversations', 'Make it safe', 'When people feel unsafe, they go silent or get aggressive. Restore safety by showing respect and clarifying shared goals.'),
  ('crucial-conversations-3', 'communication', 'crucial-conversations', 'Separate facts from stories', '"You were late three times this week" is a fact. "You don''t care" is a story. Lead with facts and offer your story tentatively.'),
  ('crucial-conversations-4', 'communication', 'crucial-conversations', 'Fill the pool of shared meaning', 'Good decisions come when everyone''s views are on the table. Invite others to share, especially when they disagree.'),
  ('nonviolent-communication-1', 'communication', 'nonviolent-communication', 'Observe without judging', 'Describe what happened like a camera would. "You left dishes in the sink" invites conversation; "You''re so lazy" invites a fight.'),
  ('nonviolent-communication-2', 'communication', 'nonviolent-communication', 'Express feelings', 'Say how you feel, using real feeling words: worried, frustrated, relieved. "I feel that you..." is usually a thought, not a feeling.'),
  ('nonviolent-communication-3', 'communication', 'nonviolent-communication', 'Connect feelings to needs', 'Behind every feeling is a need, like rest, respect or connection. Naming the need makes it easier for others to help.'),
  ('nonviolent-communication-4', 'communication', 'nonviolent-communication', 'Make clear requests', 'Ask for a specific, doable action, not a vague demand. "Could you text me if you''ll be late?" beats "Be more considerate."'),
  ('never-split-the-difference-1', 'communication', 'never-split-the-difference', 'Tactical empathy', 'Show the other side that you understand their position and feelings. People negotiate more openly when they feel heard.'),
  ('never-split-the-difference-2', 'communication', 'never-split-the-difference', 'Mirroring', 'Repeat the last few words someone said, as a question. It encourages them to keep talking and reveal more.'),
  ('never-split-the-difference-3', 'communication', 'never-split-the-difference', 'Label emotions', 'Say "It seems like you''re frustrated about the timeline." Naming emotions defuses negative ones and builds trust.'),
  ('never-split-the-difference-4', 'communication', 'never-split-the-difference', 'Aim for "that''s right"', 'When someone says "That''s right" after you summarize their view, they feel understood. That''s when real agreement becomes possible.'),
  ('never-split-the-difference-5', 'communication', 'never-split-the-difference', 'Calibrated questions', 'Ask "How am I supposed to do that?" or "What makes this important to you?" Open how and what questions make the other side solve your problem.'),
  ('talk-like-ted-1', 'communication', 'talk-like-ted', 'Unleash your passion', 'Audiences connect with speakers who clearly love their subject. Talk about what genuinely excites you.'),
  ('talk-like-ted-2', 'communication', 'talk-like-ted', 'Tell stories', 'Stories stick in memory far better than data alone. Wrap your key points in personal, vivid stories.'),
  ('talk-like-ted-3', 'communication', 'talk-like-ted', 'Keep it to 18 minutes', 'Long talks overload the brain. Shorter presentations force you to focus on what really matters.'),
  ('talk-like-ted-4', 'communication', 'talk-like-ted', 'Deliver jaw-dropping moments', 'Give the audience one surprising, memorable moment, a demo, a shocking statistic, that they''ll talk about afterwards.'),
  ('steal-like-an-artist', 'creativity', 'steal-like-an-artist', 'Nothing is completely original', 'Every creative work builds on what came before. Collect influences, study them, remix them and add your own twist. Copying one source is plagiarism; combining many and transforming them is how style is born.'),
  ('steal-like-an-artist-2', 'creativity', 'steal-like-an-artist', 'Don''t wait until you know who you are', 'If you waited until you fully understood yourself before making things, you''d never start. You figure out who you are by making things.'),
  ('steal-like-an-artist-3', 'creativity', 'steal-like-an-artist', 'Write the book you want to read', 'Instead of writing what you know, make the thing you wish existed. Your taste is your guide.'),
  ('steal-like-an-artist-4', 'creativity', 'steal-like-an-artist', 'Use your hands', 'Step away from the screen. Paper, scissors and whiteboards wake up a different part of your thinking than typing does.'),
  ('steal-like-an-artist-5', 'creativity', 'steal-like-an-artist', 'Be boring', 'Creative work needs energy. A steady routine, enough sleep and a sensible budget give you the stability to take risks in your work.'),
  ('resistance', 'creativity', 'war-of-art', 'Beat Resistance by showing up', 'The force that keeps you from your creative work, procrastination, self-doubt, sudden urges to do chores, is strongest right before something important. Professionals don''t wait for inspiration; they sit down every day and do the work.'),
  ('war-of-art-2', 'creativity', 'war-of-art', 'Resistance points to what matters', 'The more important a calling is to your growth, the more Resistance you''ll feel toward it. Fear is a compass pointing at the work you should be doing.'),
  ('war-of-art-3', 'creativity', 'war-of-art', 'Turn pro', 'Amateurs work when they feel like it. Professionals show up every day, no matter what, and treat creative work as a job.'),
  ('war-of-art-4', 'creativity', 'war-of-art', 'The muse rewards commitment', 'When you commit to the work daily, help seems to appear: ideas arrive, connections form. Inspiration follows effort, not the other way round.'),
  ('big-magic-1', 'creativity', 'big-magic', 'Let fear ride along, not drive', 'Fear will always come with you on creative journeys. Give it a seat in the car, but never let it pick the music or touch the steering wheel.'),
  ('big-magic-2', 'creativity', 'big-magic', 'Ideas look for collaborators', 'Gilbert imagines ideas as visitors searching for someone to bring them to life. If you ignore one long enough, it may move on to someone else.'),
  ('big-magic-3', 'creativity', 'big-magic', 'Done is better than good', 'Perfectionism is often fear in disguise. Finishing imperfect work teaches you more than polishing forever.'),
  ('big-magic-4', 'creativity', 'big-magic', 'Follow curiosity, not passion', 'If you can''t find your passion, follow small sparks of curiosity. They''re easier to act on and often lead somewhere surprising.'),
  ('creativity-inc-1', 'creativity', 'creativity-inc', 'Every film starts ugly', 'Early versions of Pixar movies were, in Catmull''s words, terrible. Great work comes from protecting fragile ideas while improving them over many rounds.'),
  ('creativity-inc-2', 'creativity', 'creativity-inc', 'The Braintrust', 'Pixar''s directors show work in progress to a group of peers who give candid notes but have no authority. Honest feedback without power keeps it useful.'),
  ('creativity-inc-3', 'creativity', 'creativity-inc', 'Candour is essential', 'If people hold back in meetings, problems stay hidden until it''s too late. Leaders must make it safe to say what''s not working.'),
  ('creativity-inc-4', 'creativity', 'creativity-inc', 'Failure is part of the process', 'If you''re not failing, you''re not trying anything new. Make early mistakes cheap and fast.'),
  ('the-artists-way-1', 'creativity', 'the-artists-way', 'Morning pages', 'Each morning, write three pages by hand of whatever comes to mind. Not art, just a brain dump. It clears mental clutter and quiets the inner critic.'),
  ('the-artists-way-2', 'creativity', 'the-artists-way', 'The artist date', 'Once a week, take yourself alone on a small adventure: a museum, a market, a walk somewhere new. It refills the creative well.'),
  ('the-artists-way-3', 'creativity', 'the-artists-way', 'Fill the well', 'Creativity draws on images and experiences. If you only output and never take in, you run dry.'),
  ('the-artists-way-4', 'creativity', 'the-artists-way', 'Quiet the censor', 'The inner critic is loudest at the start. Treat its comments as noise, not truth, and keep going.'),
  ('show-your-work-1', 'creativity', 'show-your-work', 'Share something small every day', 'Post a sketch, a note or a work-in-progress daily. Over time, these small shares add up to a body of work people can follow.'),
  ('show-your-work-2', 'creativity', 'show-your-work', 'Think process, not product', 'Audiences love seeing how something is made. Behind-the-scenes glimpses build connection long before the final piece is ready.'),
  ('show-your-work-3', 'creativity', 'show-your-work', 'Be an amateur', 'Amateurs share because they love the work and aren''t afraid to look foolish. That openness makes them easier to relate to than experts.'),
  ('show-your-work-4', 'creativity', 'show-your-work', 'Teach what you know', 'Explaining your methods doesn''t make you replaceable. It builds trust, and people value those who share.'),
  ('sleep-performance', 'health', 'why-we-sleep', 'Sleep is a performance tool', 'Sleep is when the brain files memories and clears waste. Regularly sleeping six hours or less hurts focus, mood and immunity, often without you noticing. Keeping a consistent wake time is one of the simplest health upgrades.'),
  ('why-we-sleep-2', 'health', 'why-we-sleep', 'Sleep before and after learning', 'Sleep before learning prepares the brain to absorb new information; sleep after learning locks it in. Pulling an all-nighter before an exam undermines both.'),
  ('why-we-sleep-3', 'health', 'why-we-sleep', 'Caffeine lingers', 'Caffeine has a half-life of around five to six hours. A coffee at 4pm can still be partly active at bedtime, making sleep lighter even if you fall asleep fine.'),
  ('why-we-sleep-4', 'health', 'why-we-sleep', 'Keep the bedroom cool and dark', 'Your body needs to drop its core temperature to fall asleep. A cool, dark room and dimmer lights in the evening help signal that it''s night.'),
  ('why-we-sleep-5', 'health', 'why-we-sleep', 'Dreams as overnight therapy', 'During REM sleep, the brain revisits emotional memories in a calmer chemical state. That''s part of why things often feel less raw after a good night''s sleep.'),
  ('walk-to-think', 'health', 'walking-study', 'Walk to think better', 'In Stanford experiments, people came up with more creative ideas while walking than while sitting, and the boost lasted shortly after they sat back down. Stuck on a problem? Take it for a walk.'),
  ('walking-study-2', 'health', 'walking-study', 'Indoors works too', 'The creativity boost showed up even when people walked on a treadmill facing a blank wall. It''s the movement itself, not just the scenery, that helps.'),
  ('walking-study-3', 'health', 'walking-study', 'Walking meetings', 'For brainstorming conversations, swap the meeting room for a walk. Side by side movement often makes talking easier and ideas looser.'),
  ('outlive-1', 'health', 'outlive', 'Healthspan over lifespan', 'Living longer is only half the goal. The other half is staying physically and mentally capable in your last decades, so those years are worth living.'),
  ('outlive-2', 'health', 'outlive', 'Exercise is the strongest medicine', 'Cardiorespiratory fitness and muscle strength are among the strongest predictors of how long and how well people live. Few drugs come close.'),
  ('outlive-3', 'health', 'outlive', 'Train for your centenarian decathlon', 'List what you want to be able to do at 90, like carrying groceries or picking up a grandchild, and train now for the strength and fitness those tasks will need.'),
  ('outlive-4', 'health', 'outlive', 'Zone 2 cardio', 'Steady exercise at a pace where you can still talk, but with effort, builds the aerobic base and metabolic health. Several hours a week pays off over decades.'),
  ('outlive-5', 'health', 'outlive', 'Prevention starts early', 'Chronic diseases like heart disease develop over decades. Acting in your thirties and forties is far more effective than reacting at sixty.'),
  ('in-defense-of-food-1', 'health', 'in-defense-of-food', 'Eat food. Not too much. Mostly plants.', 'Pollan''s whole philosophy in seven words: choose real food, keep portions moderate and make plants the bulk of your plate.'),
  ('in-defense-of-food-2', 'health', 'in-defense-of-food', 'Beware of health claims', 'Products that shout about being healthy are usually processed. Fresh vegetables rarely need a label telling you they''re good for you.'),
  ('in-defense-of-food-3', 'health', 'in-defense-of-food', 'Your great-grandmother test', 'Don''t eat anything your great-grandmother wouldn''t recognize as food. Long ingredient lists full of unfamiliar words are a warning sign.'),
  ('in-defense-of-food-4', 'health', 'in-defense-of-food', 'Shop the edges', 'In most supermarkets, fresh produce, meat and dairy sit around the walls, while processed foods fill the middle aisles.'),
  ('in-defense-of-food-5', 'health', 'in-defense-of-food', 'Eat slowly, at a table', 'Eating with others, at regular meals and without screens helps you notice when you''re full and enjoy food more.'),
  ('breath-1', 'health', 'breath', 'Breathe through your nose', 'Nasal breathing filters, warms and humidifies air and helps the body take in oxygen efficiently. Mouth breathing, especially at night, is linked to snoring and poorer sleep.'),
  ('breath-2', 'health', 'breath', 'Slow down your breathing', 'Breathing around six breaths a minute, roughly five seconds in and five out, has a calming effect on the nervous system and heart rate.'),
  ('breath-3', 'health', 'breath', 'Exhale longer to relax', 'A longer out-breath than in-breath activates the body''s rest response. It''s a quick tool before a stressful conversation.'),
  ('breath-4', 'health', 'breath', 'Breathe less, not more', 'Many people breathe more than they need. Lighter, quieter breathing can improve how efficiently oxygen reaches your tissues.'),
  ('the-body-keeps-the-score-1', 'health', 'the-body-keeps-the-score', 'Trauma is stored in the body', 'Traumatic stress isn''t only a memory; it can keep the body''s alarm system switched on, showing up as tension, fatigue or sudden reactions long after the event.'),
  ('the-body-keeps-the-score-2', 'health', 'the-body-keeps-the-score', 'Talking isn''t always enough', 'Because trauma affects brain areas below language, healing often involves the body too: movement, breathing, yoga and other ways of feeling safe again.'),
  ('the-body-keeps-the-score-3', 'health', 'the-body-keeps-the-score', 'Safety comes from connection', 'Feeling seen and supported by other people is one of the most powerful protections against the lasting effects of trauma.'),
  ('the-body-keeps-the-score-4', 'health', 'the-body-keeps-the-score', 'Reclaiming the body', 'Learning to notice bodily sensations without being overwhelmed helps people feel at home in themselves again.'),
  ('guns-germs-and-steel-1', 'history', 'guns-germs-and-steel', 'Geography shaped history', 'Diamond argues that the advantages some civilizations gained came from their environment, like which plants and animals could be domesticated, not from any innate superiority.'),
  ('guns-germs-and-steel-2', 'history', 'guns-germs-and-steel', 'The east-west axis', 'Eurasia stretches east to west, so crops and ideas could spread across similar climates. The Americas and Africa run north to south, which made spreading harder.'),
  ('guns-germs-and-steel-3', 'history', 'guns-germs-and-steel', 'Germs were decisive', 'Societies that lived closely with livestock developed immunity to many diseases. When Europeans reached the Americas, those germs killed far more people than weapons did.'),
  ('guns-germs-and-steel-4', 'history', 'guns-germs-and-steel', 'Food surpluses created specialists', 'Farming produced extra food, which supported people who didn''t farm: soldiers, scribes, inventors and rulers.'),
  ('the-histories-1', 'history', 'the-histories', 'The father of history', 'Herodotus set out to record great deeds so they wouldn''t be forgotten, and to explain why Greeks and Persians went to war. Asking why became the heart of history.'),
  ('the-histories-2', 'history', 'the-histories', 'Call no one happy until they die', 'In a famous story, the sage Solon tells a rich king that fortune can change at any time, so a life can only be judged as a whole.'),
  ('the-histories-3', 'history', 'the-histories', 'Customs differ', 'Herodotus described how different peoples saw their own customs as best. Recognizing this was an early lesson in cultural humility.'),
  ('the-histories-4', 'history', 'the-histories', 'Thermopylae', 'A small force of Greeks held a narrow pass against a vast Persian army for days. Their stand became a lasting symbol of courage.'),
  ('the-wright-brothers-1', 'history', 'the-wright-brothers', 'Outsiders solved it', 'With no college degrees or funding, Wilbur and Orville Wright beat well-financed experts by studying carefully and testing relentlessly.'),
  ('the-wright-brothers-2', 'history', 'the-wright-brothers', 'Control was the key', 'Others focused on engines and lift. The Wrights realized the real problem was balance and steering, and solved it by twisting the wings, inspired by birds.'),
  ('the-wright-brothers-3', 'history', 'the-wright-brothers', 'Build your own data', 'When existing tables on wing lift proved wrong, they built a wind tunnel and measured hundreds of wing shapes themselves.'),
  ('the-wright-brothers-4', 'history', 'the-wright-brothers', 'Persistence through failure', 'Crashes, mockery and setbacks didn''t stop them. On 17 December 1903, their flyer made the first powered, controlled flights.'),
  ('team-of-rivals-1', 'history', 'team-of-rivals', 'Hire your rivals', 'Lincoln appointed the men who had competed against him for the nomination. He valued their talents more than his own ego.'),
  ('team-of-rivals-2', 'history', 'team-of-rivals', 'Emotional intelligence in leadership', 'Lincoln shared credit, took blame, and controlled his anger by writing letters he never sent.'),
  ('team-of-rivals-3', 'history', 'team-of-rivals', 'Learn from defeat', 'Lincoln lost many elections before winning the presidency. Each setback deepened his understanding of people and politics.'),
  ('team-of-rivals-4', 'history', 'team-of-rivals', 'Timing matters', 'Lincoln waited for the right moment to issue the Emancipation Proclamation, when public opinion and the military situation could support it.'),
  ('the-silk-roads-1', 'history', 'the-silk-roads', 'The world''s crossroads', 'For most of history, the region between Europe and China was the centre of the world, where goods, ideas and religions met.'),
  ('the-silk-roads-2', 'history', 'the-silk-roads', 'More than silk', 'The routes carried spices, horses, paper, technologies and also diseases like the plague.'),
  ('the-silk-roads-3', 'history', 'the-silk-roads', 'Ideas travelled too', 'Buddhism, Christianity and Islam spread along these trade routes, as did mathematics and astronomy.'),
  ('the-silk-roads-4', 'history', 'the-silk-roads', 'The pivot returns', 'Frankopan argues that power is shifting back toward these regions, making their history vital for understanding the present.'),
  ('start-with-why', 'leadership', 'start-with-why', 'Start with why', 'Most organizations explain what they do and how they do it. Inspiring leaders start with why: the purpose or belief behind the work. People don''t just buy what you do; they buy into why you do it.'),
  ('start-with-why-2', 'leadership', 'start-with-why', 'The Golden Circle', 'Picture three rings: why at the centre, how around it and what on the outside. Inspiring communication moves from the inside out.'),
  ('start-with-why-3', 'leadership', 'start-with-why', 'Manipulation versus inspiration', 'Discounts, fear and peer pressure can drive a sale, but they don''t build loyalty. Shared belief does.'),
  ('start-with-why-4', 'leadership', 'start-with-why', 'Trust comes from consistency', 'When what you say and what you do line up with your why, people trust you. Clarity, discipline and consistency keep the circle balanced.'),
  ('extreme-ownership', 'leadership', 'extreme-ownership', 'Own everything in your world', 'When something goes wrong, a good leader doesn''t blame the team, the plan or bad luck. They take responsibility, find what they could have done better and fix it. That ownership spreads through the whole team.'),
  ('extreme-ownership-2', 'leadership', 'extreme-ownership', 'No bad teams, only bad leaders', 'The same team can fail or succeed depending on who leads it. Standards are what the leader tolerates.'),
  ('extreme-ownership-3', 'leadership', 'extreme-ownership', 'Prioritize and execute', 'When overwhelmed, step back, pick the single highest-priority problem, solve it, then move to the next. Trying to fix everything at once fixes nothing.'),
  ('extreme-ownership-4', 'leadership', 'extreme-ownership', 'Simple plans win', 'Complex plans fall apart under pressure. If everyone can''t understand the plan, it''s too complicated.'),
  ('extreme-ownership-5', 'leadership', 'extreme-ownership', 'Decentralized command', 'Leaders explain the intent, then let people closest to the action make decisions. Teams move faster when they don''t wait for approval.'),
  ('leaders-eat-last-1', 'leadership', 'leaders-eat-last', 'The circle of safety', 'When people feel protected by their leader from threats inside the organization, they focus their energy on outside challenges instead of on watching their backs.'),
  ('leaders-eat-last-2', 'leadership', 'leaders-eat-last', 'Leadership is a choice', 'Rank doesn''t make someone a leader. Choosing to look after the people around you does.'),
  ('leaders-eat-last-3', 'leadership', 'leaders-eat-last', 'Leaders take the hit', 'In the military, officers traditionally eat after their troops. Good leaders give up some of their own comfort for the people they''re responsible for.'),
  ('leaders-eat-last-4', 'leadership', 'leaders-eat-last', 'People are not numbers', 'When leaders treat people as costs on a spreadsheet, trust collapses. Seeing them as humans builds loyalty that money can''t buy.'),
  ('dare-to-lead-1', 'leadership', 'dare-to-lead', 'Clear is kind', 'Being vague to avoid an awkward conversation is unkind. Clear expectations and honest feedback, delivered with respect, help people succeed.'),
  ('dare-to-lead-2', 'leadership', 'dare-to-lead', 'Vulnerability is courage', 'Saying "I don''t know" or "I was wrong" takes courage. Leaders who can be vulnerable make it safe for others to take risks.'),
  ('dare-to-lead-3', 'leadership', 'dare-to-lead', 'Armoured versus daring leadership', 'Perfectionism, cynicism and needing to be right are armour. They protect the leader but stop the team from learning.'),
  ('dare-to-lead-4', 'leadership', 'dare-to-lead', 'Name your values', 'Choose two core values and define what they look like in action. Values only count when they guide hard decisions.'),
  ('the-five-dysfunctions-1', 'leadership', 'the-five-dysfunctions', 'Absence of trust', 'When team members can''t admit mistakes or weaknesses, everyone wastes energy protecting themselves. Trust is the foundation of every other team skill.'),
  ('the-five-dysfunctions-2', 'leadership', 'the-five-dysfunctions', 'Fear of conflict', 'Teams without trust avoid open debate. Artificial harmony leads to poor decisions because real concerns are never voiced.'),
  ('the-five-dysfunctions-3', 'leadership', 'the-five-dysfunctions', 'Lack of commitment', 'If people haven''t had a chance to weigh in, they won''t truly buy in, even if they nod in the meeting.'),
  ('the-five-dysfunctions-4', 'leadership', 'the-five-dysfunctions', 'Avoidance of accountability', 'When commitment is fuzzy, peers hesitate to call each other out. Standards slip quietly.'),
  ('the-five-dysfunctions-5', 'leadership', 'the-five-dysfunctions', 'Inattention to results', 'When individuals care more about their status or department than team goals, collective results suffer.'),
  ('the-art-of-war-1', 'leadership', 'the-art-of-war', 'Know yourself and your opponent', 'If you know both yourself and the other side, you need not fear the outcome of a hundred battles. Most failures come from ignoring one of the two.'),
  ('the-art-of-war-2', 'leadership', 'the-art-of-war', 'Win without fighting', 'The highest skill is to achieve your goal without open conflict, by outmanoeuvring, persuading or making the fight unnecessary.'),
  ('the-art-of-war-3', 'leadership', 'the-art-of-war', 'Attack weakness, avoid strength', 'Like water flowing downhill, strategy should flow around strong points and toward weak ones.'),
  ('the-art-of-war-4', 'leadership', 'the-art-of-war', 'Speed and preparation', 'Victory usually goes to whoever prepared more thoroughly beforehand. Battles are won before they begin.'),
  ('name-the-emotion', 'mindfulness', 'affect-labeling', 'Name it to tame it', 'Simply putting a feeling into words, "I feel anxious", reduces activity in the brain''s alarm system. Labeling an emotion creates a little distance between you and it, which gives you room to choose a response.'),
  ('affect-labeling-2', 'mindfulness', 'affect-labeling', 'Be specific with emotion words', '"Bad" is vague. "Disappointed", "embarrassed" or "lonely" are precise. The more exactly you can name a feeling, the easier it becomes to understand what it needs.'),
  ('affect-labeling-3', 'mindfulness', 'affect-labeling', 'Write it down', 'Spending a few minutes writing about a stressful event, in plain words, has been linked to lower stress and better wellbeing. Words on paper turn a swirl into something you can look at.'),
  ('beginners-mind', 'mindfulness', 'zen-mind', 'Keep a beginner''s mind', 'In the beginner''s mind there are many possibilities; in the expert''s mind there are few. Approach familiar things with curiosity, as if seeing them for the first time, and you will notice what habit hides.'),
  ('zen-mind-2', 'mindfulness', 'zen-mind', 'Don''t try to stop thoughts', 'In meditation, thoughts will come. Let them come and go like guests you don''t invite to stay. Fighting them only gives them more energy.'),
  ('zen-mind-3', 'mindfulness', 'zen-mind', 'Practice without gaining ideas', 'If you meditate to get something, you turn it into another task to succeed at. Just sit. The benefits come when you stop chasing them.'),
  ('zen-mind-4', 'mindfulness', 'zen-mind', 'Give your sheep a large meadow', 'To control a sheep, give it a big meadow. Likewise, to calm the mind, don''t fence it in; let it be, and simply watch.'),
  ('power-of-now-1', 'mindfulness', 'power-of-now', 'You are not your thoughts', 'There''s the voice in your head, and there''s the awareness that hears it. Noticing the voice, rather than being swept away by it, is the first step to inner calm.'),
  ('power-of-now-2', 'mindfulness', 'power-of-now', 'The present is all you ever have', 'The past exists as memory and the future as imagination; you only ever live now. Much anxiety comes from living in a future that doesn''t exist yet.'),
  ('power-of-now-3', 'mindfulness', 'power-of-now', 'Accept, then act', 'Resisting what already is creates suffering. Accept the present moment fully, then, if action is needed, act from clarity instead of frustration.'),
  ('power-of-now-4', 'mindfulness', 'power-of-now', 'Watch the pain-body', 'Old emotional pain can flare up and take over your reactions. Observing it as it rises, without feeding it with stories, weakens its grip.'),
  ('wherever-you-go-1', 'mindfulness', 'wherever-you-go', 'Mindfulness defined', 'Mindfulness means paying attention on purpose, in the present moment, without judging. It''s not about emptying your mind but noticing what''s actually there.'),
  ('wherever-you-go-2', 'mindfulness', 'wherever-you-go', 'You can''t escape yourself', 'Moving city or changing job won''t fix a restless mind, because you bring it with you. Changing your relationship with your mind travels better.'),
  ('wherever-you-go-3', 'mindfulness', 'wherever-you-go', 'Informal practice', 'You don''t need a cushion. Wash dishes, walk or drink tea with full attention. Ordinary moments become practice when you''re actually there for them.'),
  ('wherever-you-go-4', 'mindfulness', 'wherever-you-go', 'Non-doing', 'Sometimes the wisest action is to stop and do nothing for a moment. Pausing breaks the chain of automatic reactions.'),
  ('wherever-you-go-5', 'mindfulness', 'wherever-you-go', 'Patience', 'Things unfold in their own time. A butterfly can''t be helped out of its cocoon early. Patience is wisdom about timing.'),
  ('the-miracle-of-mindfulness-1', 'mindfulness', 'the-miracle-of-mindfulness', 'Wash the dishes to wash the dishes', 'If you wash dishes only to get them done, rushing to the next thing, you aren''t alive during that time. Do each task as if it were the most important thing in the world.'),
  ('the-miracle-of-mindfulness-2', 'mindfulness', 'the-miracle-of-mindfulness', 'Return to the breath', 'Your breath is always with you. When you''re scattered, a few conscious breaths bring body and mind back together.'),
  ('the-miracle-of-mindfulness-3', 'mindfulness', 'the-miracle-of-mindfulness', 'A day of mindfulness', 'Set aside one day a week, or even a morning, to do everything slowly and with full awareness. It recharges you for the busier days.'),
  ('the-miracle-of-mindfulness-4', 'mindfulness', 'the-miracle-of-mindfulness', 'Smile to relax', 'A gentle half-smile relaxes the muscles of the face and calms the mind. It''s a tiny practice you can use in traffic, queues or stressful meetings.'),
  ('radical-acceptance-1', 'mindfulness', 'radical-acceptance', 'The trance of unworthiness', 'Many of us live with a quiet sense that we''re not good enough and must keep proving ourselves. Seeing this as a trance, not a truth, is the start of freedom.'),
  ('radical-acceptance-2', 'mindfulness', 'radical-acceptance', 'RAIN', 'When a hard feeling arises: Recognize what''s happening, Allow it to be there, Investigate it with kindness, and Nurture yourself. Four steps from reactivity to care.'),
  ('radical-acceptance-3', 'mindfulness', 'radical-acceptance', 'The sacred pause', 'Between a trigger and your reaction, pause and notice. Even a few seconds of stopping can change what happens next.'),
  ('radical-acceptance-4', 'mindfulness', 'radical-acceptance', 'Acceptance is not resignation', 'Accepting a feeling doesn''t mean liking it or giving up. It means seeing clearly what''s here, which is the only place real change can start.'),
  ('pay-yourself-first', 'money', 'babylon', 'Pay yourself first', 'Before paying anyone else, set aside a fixed part of everything you earn, even a tenth. Treat it as a bill owed to your future self. Saving what is left at the end of the month rarely works, because little is ever left.'),
  ('babylon-2', 'money', 'babylon', 'Make your gold work', 'Saved money should be put to work so it earns more money, which in turn earns more. Each coin becomes a worker that brings in others.'),
  ('babylon-3', 'money', 'babylon', 'Control your expenses', 'What we call necessary expenses grow to match our income unless we push back. Budget on purpose so desires don''t swallow everything you earn.'),
  ('babylon-4', 'money', 'babylon', 'Guard against loss', 'Before chasing high returns, protect your principal. Seek advice from people experienced with money, not from those who have never managed it.'),
  ('babylon-5', 'money', 'babylon', 'Increase your ability to earn', 'The more you learn and the better you get at your work, the more you can earn. Investing in your own skills is part of building wealth.'),
  ('compounding-time', 'money', 'psychology-of-money', 'Compounding needs time, not genius', 'Most long-term wealth comes from earning decent returns for a very long time without interruption. Avoiding ruin and staying invested through bad years matters more than finding the highest return.'),
  ('psychology-of-money-2', 'money', 'psychology-of-money', 'Wealth is what you don''t see', 'Wealth is the nice car not bought and the money left in the account. Spending to look rich is the fastest way to have less money.'),
  ('psychology-of-money-3', 'money', 'psychology-of-money', 'Enough', 'The hardest financial skill is getting the goalpost to stop moving. If expectations rise with every gain, no amount will ever feel like enough.'),
  ('psychology-of-money-4', 'money', 'psychology-of-money', 'Room for error', 'Plans fail. A cash buffer and modest assumptions let you survive bad luck long enough for good luck to arrive.'),
  ('psychology-of-money-5', 'money', 'psychology-of-money', 'Freedom is the highest dividend', 'The greatest value of money is control over your time: being able to do what you want, when you want, with whom you want.'),
  ('psychology-of-money-6', 'money', 'psychology-of-money', 'Reasonable beats rational', 'A strategy you can stick with through panic is better than a theoretically perfect one you''ll abandon at the worst moment.'),
  ('rich-dad-poor-dad-1', 'money', 'rich-dad-poor-dad', 'Assets versus liabilities', 'Kiyosaki''s simple definition: an asset puts money in your pocket, a liability takes money out. Many things people call assets, like a big house, mostly drain cash.'),
  ('rich-dad-poor-dad-2', 'money', 'rich-dad-poor-dad', 'The rat race', 'Earn more, spend more, need to earn more. Escaping means building income that doesn''t depend on trading every hour for pay.'),
  ('rich-dad-poor-dad-3', 'money', 'rich-dad-poor-dad', 'Financial literacy', 'Schools rarely teach how money works. Learning to read a balance sheet and understand cash flow matters more than a high salary.'),
  ('rich-dad-poor-dad-4', 'money', 'rich-dad-poor-dad', 'Ask how you can afford it', 'Saying "I can''t afford it" shuts down thinking. Asking "How can I afford it?" pushes you to look for solutions.'),
  ('your-money-or-your-life-1', 'money', 'your-money-or-your-life', 'Money is life energy', 'Every purchase costs the hours of your life spent earning it. Work out your real hourly wage after commuting and work costs, and prices start to look different.'),
  ('your-money-or-your-life-2', 'money', 'your-money-or-your-life', 'Track every cent', 'For a month, record every penny that comes in and goes out. Awareness alone changes spending, without any strict budget.'),
  ('your-money-or-your-life-3', 'money', 'your-money-or-your-life', 'Fulfilment curve', 'Spending brings more happiness up to a point: survival, comforts, a few luxuries. Beyond "enough", more stuff brings clutter, not joy.'),
  ('your-money-or-your-life-4', 'money', 'your-money-or-your-life', 'The crossover point', 'Financial independence arrives when monthly investment income exceeds monthly expenses. Lower spending gets you there faster than higher income.'),
  ('little-book-common-sense-investing-1', 'money', 'little-book-common-sense-investing', 'Own the whole market', 'Instead of searching for the needle, buy the haystack. A broad index fund owns every company and captures the market''s return at very low cost.'),
  ('little-book-common-sense-investing-2', 'money', 'little-book-common-sense-investing', 'Costs matter enormously', 'A 1% yearly fee sounds small, but over decades it can eat a large share of your final wealth. In investing, you get what you don''t pay for.'),
  ('little-book-common-sense-investing-3', 'money', 'little-book-common-sense-investing', 'Most active funds lose', 'After fees, the majority of actively managed funds trail their index over long periods. Picking which few will win in advance is nearly impossible.'),
  ('little-book-common-sense-investing-4', 'money', 'little-book-common-sense-investing', 'Don''t just do something, stand there', 'Frequent trading adds costs and mistakes. The winning strategy is usually to buy, hold and leave it alone.'),
  ('i-will-teach-you-to-be-rich-1', 'money', 'i-will-teach-you-to-be-rich', 'Automate your money', 'Set up automatic transfers on payday for savings, investments and bills. When good decisions happen without you, you stop relying on willpower.'),
  ('i-will-teach-you-to-be-rich-2', 'money', 'i-will-teach-you-to-be-rich', 'Spend extravagantly on what you love', 'Cut mercilessly on things you don''t care about so you can spend freely on what you do. Frugality isn''t about spending less on everything.'),
  ('i-will-teach-you-to-be-rich-3', 'money', 'i-will-teach-you-to-be-rich', 'Conscious spending plan', 'A simple split: fixed costs, investments, savings goals and guilt-free spending. If the fixed costs are reasonable, the rest takes care of itself.'),
  ('i-will-teach-you-to-be-rich-4', 'money', 'i-will-teach-you-to-be-rich', 'Focus on big wins', 'Negotiating your salary or rent saves more than a lifetime of skipped coffees. Spend your energy on the few decisions that move the needle.'),
  ('dichotomy-of-control', 'philosophy', 'enchiridion', 'Separate what you control', 'Some things are up to us, our judgments, choices and efforts, and some are not, like other people''s opinions or the weather. Peace comes from putting your energy into the first group and accepting the second.'),
  ('enchiridion-2', 'philosophy', 'enchiridion', 'It''s our judgments that disturb us', 'Events themselves don''t upset us; our opinions about them do. When you feel hurt, look for the judgment behind the feeling and ask whether it''s true.'),
  ('enchiridion-3', 'philosophy', 'enchiridion', 'Want things as they are', 'Don''t demand that events happen as you wish. Wish for them to happen as they do, and life will go smoothly. This isn''t passivity; it''s refusing to fight what has already happened.'),
  ('enchiridion-4', 'philosophy', 'enchiridion', 'Remember what things are', 'If you love a cup, remind yourself that it is only a cup, so you won''t be crushed when it breaks. Holding things lightly lets you enjoy them without dread.'),
  ('enchiridion-5', 'philosophy', 'enchiridion', 'Act your part well', 'Life is like a play: you didn''t choose your role, but you can choose to play it well. Focus on doing your part with skill rather than envying someone else''s.'),
  ('memento-mori', 'philosophy', 'meditations', 'Remember that you will die', 'The Stoics reminded themselves daily that life is short. Not to be gloomy, but to sharpen priorities: if today were among your last, would petty grudges or endless scrolling still feel worth it?'),
  ('meditations-2', 'philosophy', 'meditations', 'Prepare for difficult people', 'Marcus began some days by expecting to meet rude, ungrateful people. Not out of cynicism: anticipating it meant he could respond with patience instead of surprise and anger.'),
  ('meditations-3', 'philosophy', 'meditations', 'The obstacle becomes the way', 'What stands in the way of an action can itself become the material for a new action. A setback is a chance to practise patience, courage or creativity.'),
  ('meditations-4', 'philosophy', 'meditations', 'Retreat into yourself', 'People seek peace in the country or by the sea, but you can find it at any moment by turning inward. A calm mind is a retreat you carry everywhere.'),
  ('meditations-5', 'philosophy', 'meditations', 'Do the work of a human being', 'On mornings when he didn''t want to get up, Marcus reminded himself that he was made to work with others, not to lie under blankets. Purpose is a better alarm than pleasure.'),
  ('meditations-6', 'philosophy', 'meditations', 'Everything is change', 'Nature loves to turn things into other things. Mountains erode, empires fall, people age. Seeing change as the normal order makes loss easier to accept.'),
  ('letters-from-a-stoic-1', 'philosophy', 'letters-from-a-stoic', 'Life is long if you know how to use it', 'We don''t have too little time; we waste a lot of it. Seneca urges guarding your hours as carefully as money, since time is the one thing you can''t earn back.'),
  ('letters-from-a-stoic-2', 'philosophy', 'letters-from-a-stoic', 'Rehearse poverty', 'Set aside a few days to live on very little, eat plain food and wear rough clothes, then ask: is this what I feared? Practising hardship removes its power over you.'),
  ('letters-from-a-stoic-3', 'philosophy', 'letters-from-a-stoic', 'We suffer more in imagination', 'Most of what we fear never happens, and what does happen is rarely as bad as we pictured. Deal with real problems, not imagined ones.'),
  ('letters-from-a-stoic-4', 'philosophy', 'letters-from-a-stoic', 'Choose friends carefully', 'Spend time with people who make you better, and whom you can make better. Habits and values are contagious.'),
  ('letters-from-a-stoic-5', 'philosophy', 'letters-from-a-stoic', 'Read deeply, not widely', 'Skipping between many books leaves nothing behind. Stay with a few great minds, and each day take one idea to digest.'),
  ('nicomachean-ethics-1', 'philosophy', 'nicomachean-ethics', 'Happiness is an activity', 'For Aristotle, happiness (eudaimonia) isn''t a passing mood but living well over a whole life: using your abilities fully and acting with virtue.'),
  ('nicomachean-ethics-2', 'philosophy', 'nicomachean-ethics', 'The golden mean', 'Each virtue sits between two extremes. Courage lies between cowardice and recklessness; generosity between stinginess and waste. Wisdom is finding the right amount for the situation.'),
  ('nicomachean-ethics-3', 'philosophy', 'nicomachean-ethics', 'We become what we repeatedly do', 'We become just by doing just acts and brave by doing brave acts. Character isn''t something you''re born with; it''s built by practice until it becomes second nature.'),
  ('nicomachean-ethics-4', 'philosophy', 'nicomachean-ethics', 'Three kinds of friendship', 'Some friendships are based on usefulness, some on pleasure, and the rarest on admiring each other''s character. Only the last kind survives changing circumstances.'),
  ('nicomachean-ethics-5', 'philosophy', 'nicomachean-ethics', 'Practical wisdom', 'Knowing general rules isn''t enough. Practical wisdom is the skill of seeing what a particular situation calls for, and it grows with experience.'),
  ('tao-te-ching-1', 'philosophy', 'tao-te-ching', 'Be like water', 'Water is soft and yields to everything, yet it wears down the hardest stone. Gentleness and persistence often overcome force.'),
  ('tao-te-ching-2', 'philosophy', 'tao-te-ching', 'Wu wei: effortless action', 'Wu wei means acting without forcing, like a skilled craftsman whose work flows. Don''t push against the grain of situations; find where they naturally lead.'),
  ('tao-te-ching-3', 'philosophy', 'tao-te-ching', 'The usefulness of emptiness', 'A bowl is useful because of its empty centre; a room because of its open space. What isn''t there can matter as much as what is.'),
  ('tao-te-ching-4', 'philosophy', 'tao-te-ching', 'Knowing when enough is enough', 'Those who know they have enough are rich. Endless wanting is a kind of poverty no amount of wealth can cure.'),
  ('tao-te-ching-5', 'philosophy', 'tao-te-ching', 'The best leaders are barely noticed', 'When the best leader''s work is done, the people say, "We did it ourselves." Great leadership empowers rather than commands.'),
  ('the-republic-1', 'philosophy', 'the-republic', 'The allegory of the cave', 'Prisoners chained in a cave see only shadows and think they''re reality. One escapes, sees the sun and returns, but the others mock him. Education is turning toward the light, and it can be uncomfortable.'),
  ('the-republic-2', 'philosophy', 'the-republic', 'The ring of Gyges', 'If you had a ring that made you invisible, would you still act justly? Plato uses this question to ask whether people are good only because they fear getting caught.'),
  ('the-republic-3', 'philosophy', 'the-republic', 'The tripartite soul', 'Plato saw the soul as reason, spirit and appetite, like a charioteer steering two horses. A just person lets reason guide, with spirit as its ally and appetite kept in check.'),
  ('the-republic-4', 'philosophy', 'the-republic', 'Philosopher kings', 'Plato argued that cities would be best ruled by those who love wisdom and don''t want power. The people who seek power most eagerly are often the least fit to hold it.'),
  ('two-minute-rule', 'productivity', 'gtd', 'The two-minute rule', 'If a task takes less than two minutes, do it now. Writing it down, tracking it and coming back to it later costs more attention than simply finishing it. Small tasks left undone pile up into a background hum of stress.'),
  ('gtd-2', 'productivity', 'gtd', 'Your mind is for having ideas', 'Your brain is a poor filing cabinet. Every open loop you try to remember keeps nagging you at the wrong moments. Capture everything in a trusted inbox outside your head and your attention is freed for actual thinking.'),
  ('gtd-3', 'productivity', 'gtd', 'Define the next physical action', '"Plan the party" is not a task, it''s a project. The next action is something visible you can do right now, like "text Sara to ask about Saturday". Vague items get avoided; concrete actions get done.'),
  ('gtd-4', 'productivity', 'gtd', 'Projects are anything with two steps', 'Any outcome that takes more than one action is a project. Keep a list of them so none silently stall, and make sure each one always has at least one next action attached.'),
  ('gtd-5', 'productivity', 'gtd', 'Do a weekly review', 'Once a week, empty your inboxes, look over every project and calendar, and decide what''s next. The review is what keeps the system trustworthy; without it, lists go stale and your head takes over again.'),
  ('gtd-6', 'productivity', 'gtd', 'Organize by context', 'Group actions by where or with what you can do them: at the computer, on the phone, errands, at home. When you''re in that context, you pick from a short relevant list instead of scanning everything.'),
  ('eat-the-frog', 'productivity', 'eat-that-frog', 'Eat the frog first', 'Start your day with the hardest, most important task, the one you are most likely to put off. Once it is done, everything else feels lighter, and you have already won the day before distractions arrive.'),
  ('eat-that-frog-2', 'productivity', 'eat-that-frog', 'Plan every day in advance', 'Spending ten minutes planning the night before saves far more time during the day. You wake up knowing exactly what to start with, and your subconscious keeps working on the plan while you sleep.'),
  ('eat-that-frog-3', 'productivity', 'eat-that-frog', 'Apply the 80/20 rule', 'Roughly 20% of your tasks produce 80% of your results. Before starting, ask which items on your list are in that vital few, and give them your best hours.'),
  ('eat-that-frog-4', 'productivity', 'eat-that-frog', 'Think about consequences', 'The most important tasks are the ones with the biggest long-term consequences, good or bad, depending on whether you do them. Use that test to rank what really deserves your attention.'),
  ('eat-that-frog-5', 'productivity', 'eat-that-frog', 'Slice the task', 'Big tasks feel overwhelming, so cut them into thin slices and finish just one. Completing a slice builds momentum, and you often keep going long after you meant to stop.'),
  ('eat-that-frog-6', 'productivity', 'eat-that-frog', 'Single-handle each task', 'Once you start an important task, keep at it until it''s done. Stopping and restarting costs time and energy each time you have to get back into it.'),
  ('parkinsons-law', 'productivity', 'parkinsons-law', 'Work expands to fill the time', 'A task given a week will take a week; the same task given an afternoon often gets done in an afternoon. Setting tighter, deliberate deadlines forces you to focus on what actually matters and skip the polishing nobody asked for.'),
  ('parkinsons-law-2', 'productivity', 'parkinsons-law', 'Organizations grow regardless of work', 'Parkinson noticed that the number of officials tends to grow whether the workload rises, falls or disappears. Managers multiply subordinates, not rivals, and those people then create work for each other.'),
  ('parkinsons-law-3', 'productivity', 'parkinsons-law', 'The law of triviality', 'Committees spend the most time on the items they understand best, not the ones that matter most. A bike shed gets an hour of debate; a nuclear reactor gets approved in minutes because few dare to discuss it.'),
  ('parkinsons-law-4', 'productivity', 'parkinsons-law', 'Use artificial deadlines', 'Because effort stretches to fit the time available, giving yourself a short, visible deadline is one of the cheapest productivity tools. Timebox a task and stop when the box ends.'),
  ('deep-work', 'productivity', 'deep-work', 'Protect blocks of deep work', 'Valuable work, like learning hard things or creating something new, needs long stretches of undistracted focus. Schedule those blocks like meetings, close the inbox and silence the phone. Shallow busywork can fill the gaps around them.'),
  ('deep-work-2', 'productivity', 'deep-work', 'Attention residue', 'When you switch from task A to task B, part of your attention stays stuck on A. Quick email checks leave a residue that lowers your performance for a while afterwards. Batch distractions instead of sprinkling them.'),
  ('deep-work-3', 'productivity', 'deep-work', 'Embrace boredom', 'If you reach for your phone every time you''re bored, your brain loses the ability to tolerate a lack of novelty, and deep focus becomes impossible. Practice waiting in line without a screen.'),
  ('deep-work-4', 'productivity', 'deep-work', 'Choose a depth philosophy', 'Some people go monastic and cut almost all shallow work. Others use a rhythm, like two deep hours every morning. Pick the style that fits your job instead of hoping focus will just happen.'),
  ('deep-work-5', 'productivity', 'deep-work', 'Have a shutdown ritual', 'End the workday with a fixed routine: review open tasks, plan tomorrow, then say a phrase like "shutdown complete". It tells your mind it''s safe to stop thinking about work, which restores energy for the next day.'),
  ('deep-work-6', 'productivity', 'deep-work', 'Quit low-value networks', 'Judge each tool by whether its benefits clearly outweigh its costs to your most important goals, not just whether it has some benefit. Most apps pass the weak test and fail the strong one.'),
  ('essentialism-1', 'productivity', 'essentialism', 'Less but better', 'Trying to do everything spreads you a millimetre deep in a thousand directions. An essentialist asks what is truly vital and gives that full energy, accepting that saying no to good things is the price.'),
  ('essentialism-2', 'productivity', 'essentialism', 'If it isn''t a clear yes, it''s a no', 'When deciding whether to take something on, score it from 0 to 100. Anything under 90 becomes a zero. This feels extreme, but it keeps room for the rare opportunities that really matter.'),
  ('essentialism-3', 'productivity', 'essentialism', 'You always have a choice', 'Phrases like "I have to" hide the fact that you are choosing. Once you admit that you choose how you spend your time, others stop deciding it for you by default.'),
  ('essentialism-4', 'productivity', 'essentialism', 'Create a buffer', 'Things almost always take longer than planned. Add a 50% buffer to estimates and you stop living in a constant state of being late and stressed.'),
  ('essentialism-5', 'productivity', 'essentialism', 'Remove obstacles', 'Instead of pushing harder, ask what is slowing the work down and remove it. Taking away a single constraint can speed everything up more than extra effort ever could.'),
  ('essentialism-6', 'productivity', 'essentialism', 'Protect your sleep', 'Essentialists see sleep as an asset, not a luxury. Losing an hour of sleep to gain an hour of work usually costs more in judgment and creativity than it gains.'),
  ('make-time-1', 'productivity', 'make-time', 'Pick a daily highlight', 'Each morning choose one thing you want to make time for today: a task, a moment with family, a run. It doesn''t replace your to-do list, it gives the day a centre so it doesn''t vanish into busywork.'),
  ('make-time-2', 'productivity', 'make-time', 'Laser mode', 'Make distraction harder: log out of social apps, remove email from your phone, keep the phone in another room. Willpower fails; friction works.'),
  ('make-time-3', 'productivity', 'make-time', 'Busy Bandwagon and Infinity Pools', 'Two forces steal your time: the culture of constant busyness, and apps with endless content. Recognize them as defaults you can opt out of, not laws of nature.'),
  ('make-time-4', 'productivity', 'make-time', 'Energize with movement and real food', 'Focus depends on energy. Short walks, regular meals with real food, enough water and some daylight are basic fuel for attention, not extras.'),
  ('make-time-5', 'productivity', 'make-time', 'Reflect each night', 'Before bed, jot down whether you made time for your highlight and what helped or hurt. Small experiments plus honest notes turn into a routine that actually fits you.'),
  ('four-thousand-weeks-1', 'productivity', 'four-thousand-weeks', 'You will never clear the list', 'An average life is about four thousand weeks. There will always be more to do than time to do it. Accepting this is a relief: the goal becomes choosing well, not finishing everything.'),
  ('four-thousand-weeks-2', 'productivity', 'four-thousand-weeks', 'The efficiency trap', 'The faster you process email, the more email you get. Getting more efficient often just fills your life with more stuff. Decide what to neglect on purpose.'),
  ('four-thousand-weeks-3', 'productivity', 'four-thousand-weeks', 'Pay yourself first, in time', 'If you wait until other obligations are done to work on what matters, that time never comes. Give the important project the first hour of the day, before the rest of the world gets it.'),
  ('four-thousand-weeks-4', 'productivity', 'four-thousand-weeks', 'Limit work in progress', 'Fix a small number of projects you''re actively working on, maybe three. Nothing new starts until one finishes. This forces you to face trade-offs instead of keeping everything half-done.'),
  ('four-thousand-weeks-5', 'productivity', 'four-thousand-weeks', 'Cosmic insignificance therapy', 'In the grand scheme your life is tiny, and that''s freeing. You don''t need to do something world-changing; ordinary moments done with attention are already worthwhile.'),
  ('four-thousand-weeks-6', 'productivity', 'four-thousand-weeks', 'Practice doing nothing', 'Sitting still for a few minutes, resisting the urge to fix or improve anything, trains you to tolerate discomfort. That tolerance is the real skill behind focus.'),
  ('the-one-thing-1', 'productivity', 'the-one-thing', 'The focusing question', 'Ask: "What''s the one thing I can do such that by doing it everything else will be easier or unnecessary?" Use it for the day, the week and your life. It cuts any to-do list down to its lead domino.'),
  ('the-one-thing-2', 'productivity', 'the-one-thing', 'The domino effect', 'A domino can knock over another one 50% bigger. Line up the right small wins in sequence and they topple into huge results. Success is built one right thing at a time.'),
  ('the-one-thing-3', 'productivity', 'the-one-thing', 'Multitasking is a lie', 'You can do two things at once, but you can''t focus on two things at once. Each switch costs time and quality. Give your one thing your full attention.'),
  ('the-one-thing-4', 'productivity', 'the-one-thing', 'Time block your one thing', 'Block out about four hours a day for your most important work and defend it like an appointment with your boss. Everything else gets fitted around it.'),
  ('the-one-thing-5', 'productivity', 'the-one-thing', 'Willpower is a battery', 'Willpower drains as the day goes on. Do your most important work early, before decisions and temptations have used up your reserve.'),
  ('habit-stacking', 'psychology', 'atomic-habits', 'Stack new habits on old ones', 'Attach a habit you want to an existing routine: "After I pour my morning coffee, I will write one sentence in my journal." The old habit becomes a reliable cue, so you no longer depend on remembering or on motivation.'),
  ('one-percent', 'psychology', 'atomic-habits', 'Tiny gains compound', 'Getting 1% better each day barely shows at first, but small improvements compound like interest. Focus on the system you follow every day rather than the goal; results are a lagging measure of your habits.'),
  ('atomic-habits-3', 'psychology', 'atomic-habits', 'The four laws of behaviour change', 'To build a habit, make it obvious, attractive, easy and satisfying. To break one, flip each law: make it invisible, unattractive, difficult and unsatisfying.'),
  ('atomic-habits-4', 'psychology', 'atomic-habits', 'Identity-based habits', 'Instead of "I want to run a marathon", think "I am a runner". Every action is a vote for the type of person you want to become. Habits stick when they match your identity.'),
  ('atomic-habits-5', 'psychology', 'atomic-habits', 'The two-minute version', 'Scale any new habit down until it takes two minutes: "read before bed" becomes "read one page". Master showing up first; you can''t improve a habit that doesn''t exist.'),
  ('atomic-habits-6', 'psychology', 'atomic-habits', 'Design your environment', 'Make good choices the path of least resistance. Put the guitar in the middle of the room, keep fruit on the counter, hide the snacks. Environment beats motivation over time.'),
  ('system-1-2', 'psychology', 'thinking-fast-slow', 'Two systems of thinking', 'System 1 is fast, automatic and intuitive. System 2 is slow, effortful and logical. Most errors happen when System 1 answers a question that needed System 2. For decisions that matter, slow down and check your first impression.'),
  ('thinking-fast-slow-2', 'psychology', 'thinking-fast-slow', 'Anchoring', 'The first number you hear pulls your estimate towards it, even when it''s random. Negotiators who name a price first often set the frame for the whole conversation.'),
  ('thinking-fast-slow-3', 'psychology', 'thinking-fast-slow', 'Losses loom larger than gains', 'Losing $100 feels roughly twice as bad as winning $100 feels good. This loss aversion makes us cling to bad investments and avoid sensible risks.'),
  ('thinking-fast-slow-4', 'psychology', 'thinking-fast-slow', 'What you see is all there is', 'Your mind builds a confident story from whatever information is in front of it and rarely asks what''s missing. Before judging, ask what you don''t know.'),
  ('thinking-fast-slow-5', 'psychology', 'thinking-fast-slow', 'The planning fallacy', 'We estimate projects based on the best-case scenario and ignore how long similar projects actually took. Look at the base rate of comparable cases before you commit to a deadline.'),
  ('thinking-fast-slow-6', 'psychology', 'thinking-fast-slow', 'The experiencing and remembering self', 'We judge experiences mostly by their peak and their ending, not their length. A holiday with a great last day is remembered more fondly than a longer one that ended badly.'),
  ('influence-1', 'psychology', 'influence', 'Reciprocity', 'People feel obliged to return favours. A free sample, a small gift or a bit of help first makes others far more likely to agree to a request later.'),
  ('influence-2', 'psychology', 'influence', 'Commitment and consistency', 'Once we take a stand, even a small one, we feel pressure to act consistently with it. Getting someone to agree to a tiny request makes a bigger one easier.'),
  ('influence-3', 'psychology', 'influence', 'Social proof', 'When unsure, we look at what others are doing. Reviews, crowds and "most people choose this" messages work because copying the group is usually a safe shortcut.'),
  ('influence-4', 'psychology', 'influence', 'Liking', 'We say yes to people we like: those who are similar to us, who compliment us, or who cooperate with us toward a shared goal.'),
  ('influence-5', 'psychology', 'influence', 'Authority', 'Titles, uniforms and confident expertise trigger automatic deference. Useful when the authority is real; dangerous when it''s only a costume.'),
  ('influence-6', 'psychology', 'influence', 'Scarcity', 'Things seem more valuable when they''re rare or about to disappear. "Only 3 left" and "offer ends tonight" exploit our fear of missing out.'),
  ('mindset-1', 'psychology', 'mindset', 'Fixed versus growth mindset', 'With a fixed mindset you believe talent is set at birth, so every challenge is a test you might fail. With a growth mindset you see ability as something you build, so challenges become ways to improve.'),
  ('mindset-2', 'psychology', 'mindset', 'Praise effort, not intelligence', 'Children praised for being smart tend to avoid hard tasks to protect that label. Children praised for effort and strategy choose harder problems and keep trying after failure.'),
  ('mindset-3', 'psychology', 'mindset', 'The power of "yet"', '"I can''t do this" becomes "I can''t do this yet". One small word turns a verdict into a stage of learning.'),
  ('mindset-4', 'psychology', 'mindset', 'Failure as information', 'In a growth mindset, a setback tells you what to work on next, not who you are. People who see it this way recover faster and learn more.'),
  ('mindset-5', 'psychology', 'mindset', 'Mindsets can be mixed', 'Nobody is pure growth mindset. You might feel growth-minded about work and fixed about art. Notice what triggers your fixed voice and talk back to it.'),
  ('mans-search-for-meaning-1', 'psychology', 'mans-search-for-meaning', 'The last human freedom', 'Frankl saw that even when everything is taken away, a person keeps one freedom: to choose their attitude toward the circumstances. That inner choice can''t be confiscated.'),
  ('mans-search-for-meaning-2', 'psychology', 'mans-search-for-meaning', 'Meaning makes suffering bearable', 'Prisoners who held on to a reason to live, a loved one to see again, work to finish, endured more than those who lost hope. Suffering without meaning crushes; suffering with meaning can be carried.'),
  ('mans-search-for-meaning-3', 'psychology', 'mans-search-for-meaning', 'Three sources of meaning', 'We find meaning by creating a work or doing a deed, by experiencing something or loving someone, and by the attitude we take toward unavoidable suffering.'),
  ('mans-search-for-meaning-4', 'psychology', 'mans-search-for-meaning', 'Life asks the questions', 'Stop asking what you expect from life and ask what life expects from you. Meaning is found by responding to concrete situations, not by thinking about it in the abstract.'),
  ('mans-search-for-meaning-5', 'psychology', 'mans-search-for-meaning', 'Success as a side effect', 'Happiness and success can''t be pursued directly; they follow from dedicating yourself to something larger than yourself.'),
  ('predictably-irrational-1', 'psychology', 'predictably-irrational', 'The decoy effect', 'Add a clearly worse option next to one of two choices and people flock to the one it resembles. A pricey "print only" subscription makes "print + web" at the same price look like a bargain.'),
  ('predictably-irrational-2', 'psychology', 'predictably-irrational', 'The power of free', 'Zero is not just another price. People will choose a free item over a much better deal that costs a few cents, because free feels like there''s no downside.'),
  ('predictably-irrational-3', 'psychology', 'predictably-irrational', 'Social norms versus market norms', 'Ask a friend to help you move and they''ll gladly do it. Offer them $10 and it feels insulting. Mixing money into social relationships changes the rules, often for the worse.'),
  ('predictably-irrational-4', 'psychology', 'predictably-irrational', 'The IKEA effect', 'We overvalue things we built ourselves, even badly. Effort creates attachment, which is why a little customer involvement makes products feel more valuable.'),
  ('predictably-irrational-5', 'psychology', 'predictably-irrational', 'Keeping doors open', 'We waste effort keeping options alive even when they have little value. Closing some doors on purpose frees energy for the ones that matter.'),
  ('the-five-love-languages-1', 'relationships', 'the-five-love-languages', 'People feel love differently', 'The five love languages are words of affirmation, quality time, gifts, acts of service and physical touch. Most of us have one or two that matter most.'),
  ('the-five-love-languages-2', 'relationships', 'the-five-love-languages', 'Speak their language, not yours', 'We tend to show love in the way we want to receive it. If your partner values acts of service, a heartfelt card might not land as much as doing the dishes.'),
  ('the-five-love-languages-3', 'relationships', 'the-five-love-languages', 'Keep the love tank full', 'When people feel loved in their own language, they handle stress and conflict better. Small daily gestures add up.'),
  ('the-five-love-languages-4', 'relationships', 'the-five-love-languages', 'Love is a choice', 'Early infatuation fades. Lasting love comes from choosing to care for someone in ways that matter to them.'),
  ('attached-1', 'relationships', 'attached', 'Three attachment styles', 'Secure people are comfortable with closeness. Anxious people crave it and fear losing it. Avoidant people value independence and pull away when things get close.'),
  ('attached-2', 'relationships', 'attached', 'Needing others isn''t weakness', 'Depending on a partner is part of being human. Secure relationships let both people be more independent, not less.'),
  ('attached-3', 'relationships', 'attached', 'The anxious-avoidant trap', 'Anxious and avoidant partners often attract each other, then trigger each other''s fears in a painful cycle.'),
  ('attached-4', 'relationships', 'attached', 'Effective communication', 'Saying what you need clearly and calmly shows you who can meet those needs, and helps a good partner do so.'),
  ('seven-principles-marriage-1', 'relationships', 'seven-principles-marriage', 'The four horsemen', 'Criticism, contempt, defensiveness and stonewalling predict break-ups. Contempt, treating your partner as beneath you, is the most damaging.'),
  ('seven-principles-marriage-2', 'relationships', 'seven-principles-marriage', 'Turn toward bids', 'Partners constantly make small bids for attention: "Look at that bird." Responding with interest, even briefly, builds connection over time.'),
  ('seven-principles-marriage-3', 'relationships', 'seven-principles-marriage', 'Love maps', 'Strong couples know each other''s worlds: worries, friends, dreams. Keep updating your map by asking questions.'),
  ('seven-principles-marriage-4', 'relationships', 'seven-principles-marriage', 'Five to one', 'Stable couples have roughly five positive interactions for every negative one during conflict. Kindness doesn''t need to be grand, just frequent.'),
  ('seven-principles-marriage-5', 'relationships', 'seven-principles-marriage', 'Some problems are permanent', 'Many disagreements never fully go away. Successful couples learn to talk about them with humour and acceptance instead of gridlock.'),
  ('the-art-of-loving-1', 'relationships', 'the-art-of-loving', 'Love is an art', 'Like music or painting, love requires knowledge, practice and effort. We focus on being lovable, and neglect learning to love.'),
  ('the-art-of-loving-2', 'relationships', 'the-art-of-loving', 'Love is active', 'Love is giving, not just receiving: care, responsibility, respect and knowledge of the other person.'),
  ('the-art-of-loving-3', 'relationships', 'the-art-of-loving', 'Mature love keeps two people whole', 'Immature love says, "I love you because I need you." Mature love says, "I need you because I love you."'),
  ('the-art-of-loving-4', 'relationships', 'the-art-of-loving', 'Self-love isn''t selfishness', 'Respecting and caring for yourself is the ground from which you can love others well.'),
  ('the-good-life-1', 'relationships', 'the-good-life', 'Relationships keep us healthy', 'In the longest study of adult life, the quality of people''s relationships predicted their health and happiness in old age better than wealth or fame.'),
  ('the-good-life-2', 'relationships', 'the-good-life', 'Loneliness is a health risk', 'Chronic loneliness is linked to poorer health and shorter lives. Social connection is as important as diet and exercise.'),
  ('the-good-life-3', 'relationships', 'the-good-life', 'Social fitness', 'Relationships need regular exercise too. Reach out, check in and make time, or connections slowly weaken.'),
  ('the-good-life-4', 'relationships', 'the-good-life', 'Small moments matter', 'A chat with a neighbour or barista counts. Brief, warm interactions boost mood and sense of belonging.'),
  ('a-brief-history-of-time-1', 'science', 'a-brief-history-of-time', 'The universe had a beginning', 'Observations show galaxies moving away from each other. Run the film backwards and everything converges to a hot, dense starting point: the Big Bang.'),
  ('a-brief-history-of-time-2', 'science', 'a-brief-history-of-time', 'Black holes', 'When a massive star collapses, gravity can become so strong that not even light escapes. The boundary of no return is called the event horizon.'),
  ('a-brief-history-of-time-3', 'science', 'a-brief-history-of-time', 'Hawking radiation', 'Hawking showed that black holes aren''t entirely black: quantum effects let them slowly emit radiation and, over immense times, evaporate.'),
  ('a-brief-history-of-time-4', 'science', 'a-brief-history-of-time', 'Space and time are one', 'Einstein''s relativity joined space and time into spacetime, which mass and energy bend. Gravity is the effect of that bending.'),
  ('cosmos-1', 'science', 'cosmos', 'We are made of star stuff', 'The carbon, oxygen and iron in our bodies were forged inside stars that exploded long ago. We are, quite literally, a way for the cosmos to know itself.'),
  ('cosmos-2', 'science', 'cosmos', 'Science as a candle in the dark', 'Science is a method for not fooling ourselves: test ideas against evidence, and change your mind when the evidence demands it.'),
  ('cosmos-3', 'science', 'cosmos', 'The cosmic calendar', 'Squeeze the universe''s history into one year and all of recorded human history fits into the last few seconds of December 31st.'),
  ('cosmos-4', 'science', 'cosmos', 'Eratosthenes measured the Earth', 'Over two thousand years ago, by comparing shadows in two Egyptian cities, Eratosthenes estimated Earth''s circumference with remarkable accuracy.'),
  ('the-selfish-gene-1', 'science', 'the-selfish-gene', 'Genes as the unit of selection', 'Dawkins argues that evolution is best seen from the gene''s point of view: bodies are vehicles built by genes that happened to copy themselves successfully.'),
  ('the-selfish-gene-2', 'science', 'the-selfish-gene', 'Selfish genes can make kind animals', 'Genes that lead to helping relatives or cooperating can spread, because relatives share copies of those genes. "Selfish" genes don''t mean selfish behaviour.'),
  ('the-selfish-gene-3', 'science', 'the-selfish-gene', 'Memes', 'Dawkins coined the word meme for ideas, tunes or habits that spread from mind to mind, competing and evolving a bit like genes.'),
  ('the-selfish-gene-4', 'science', 'the-selfish-gene', 'Tit for tat', 'In repeated games, a simple strategy of cooperating first, then copying what the other did last time, does remarkably well. Cooperation can evolve from self-interest.'),
  ('the-gene-1', 'science', 'the-gene', 'Mendel''s peas', 'A monk crossing pea plants in a monastery garden discovered that traits pass down in discrete units, which we now call genes.'),
  ('the-gene-2', 'science', 'the-gene', 'DNA''s double helix', 'DNA is two strands twisted together, with bases pairing A with T and C with G. Each strand can serve as a template to copy the other.'),
  ('the-gene-3', 'science', 'the-gene', 'Genes are recipes, not destinies', 'Most traits come from many genes interacting with environment and chance. Having a gene variant changes probabilities, not certainties.'),
  ('the-gene-4', 'science', 'the-gene', 'The power and danger of editing', 'Tools like CRISPR let scientists change DNA precisely. They could cure diseases, but also raise deep ethical questions about changing future generations.'),
  ('sapiens-1', 'science', 'sapiens', 'The cognitive revolution', 'Around 70,000 years ago, humans began to speak about things that don''t physically exist. Shared stories let large groups of strangers cooperate.'),
  ('sapiens-2', 'science', 'sapiens', 'Shared fictions', 'Nations, money and companies exist because many people believe in them together. These shared myths are humanity''s superpower.'),
  ('sapiens-3', 'science', 'sapiens', 'The agricultural trap', 'Farming fed more people but often meant harder work, worse diets and more disease for individuals. Wheat, Harari jokes, domesticated humans.'),
  ('sapiens-4', 'science', 'sapiens', 'Money is trust', 'Money works because everyone believes everyone else will accept it. It''s the most universal system of mutual trust ever created.'),
  ('sapiens-5', 'science', 'sapiens', 'The scientific revolution began with ignorance', 'Modern science started when people admitted they didn''t know important things, and set out to find out.'),
  ('the-structure-of-scientific-revolutions-1', 'science', 'the-structure-of-scientific-revolutions', 'Paradigms', 'Scientists work inside a shared framework of assumptions, methods and examples. Kuhn called it a paradigm.'),
  ('the-structure-of-scientific-revolutions-2', 'science', 'the-structure-of-scientific-revolutions', 'Normal science', 'Most research is puzzle-solving within the paradigm, filling in details rather than questioning the foundations.'),
  ('the-structure-of-scientific-revolutions-3', 'science', 'the-structure-of-scientific-revolutions', 'Anomalies pile up', 'Results that don''t fit accumulate until the old paradigm can''t absorb them, and a crisis begins.'),
  ('the-structure-of-scientific-revolutions-4', 'science', 'the-structure-of-scientific-revolutions', 'Paradigm shifts', 'Eventually a new framework replaces the old one, as when Copernicus moved the Sun to the centre. Afterwards, scientists see the world differently.')
